
.app-container {
  font-family: 'Inter', ui-sans-serif, system-ui, -apple-system, sans-serif;
  max-width: 800px;
  margin: 40px auto;
  padding: 0 20px;
}

.header {
  position: relative;
  text-align: center;
  margin-bottom: 40px;
}

.header-text {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.theme-toggle {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 10;
  background: var(--color-paper);
  border: none;
  border-radius: var(--radius-full);
  width: 45px;
  height: 45px;
  font-size: 1.5rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease;
  box-shadow: var(--shadow-subtle);
}

.theme-toggle:hover {
  transform: scale(1.05);
}

/* ===== INTRO ===== */
.intro {
  margin: 0 auto 40px;
  text-align: center;
}

.pill {
  display: inline-flex;
  margin-top: 4px;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  background: var(--color-paper);
  color: var(--color-forest-ink);
  font-size: 14px;
  font-weight: 700;
  box-shadow: var(--shadow-subtle);
}

.pill-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-lime-voltage);
}

.answer-card {
  text-align: left;
  padding: 32px 36px;
  border-radius: var(--radius-3xl);
  background: var(--color-paper);
  box-shadow: var(--shadow-subtle), var(--shadow-lg);
  margin-bottom: 40px;
}

.answer-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 18px;
  font-size: 12px;
}

.answer-label {
  color: var(--color-charcoal);
  font-weight: 700;
  letter-spacing: 0.05em;
}

.answer-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-lime-voltage);
}

.answer-text {
  margin: 0;
  font-size: 18px;
  line-height: 1.5;
  color: var(--color-obsidian);
}

.answer-text strong {
  font-weight: 700;
}

.body-text {
  text-align: left;
  margin: 0 0 28px;
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-charcoal);
}

/* ===== ZOEKKAART ===== */
.search-card {
  background: var(--color-paper);
  padding: 32px 24px;
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-subtle), var(--shadow-lg);
  margin-bottom: 32px;
  width: 100%;
  box-sizing: border-box;
}

.input-group {
  display: flex;
  gap: 12px;
  margin-bottom: 32px;
}

.modern-input, .modern-select {
  flex: 1;
  padding: 16px 20px;
  font-size: 16px;
  border: none;
  border-radius: var(--radius-lg);
  background-color: var(--color-paper) !important;
  color: var(--color-obsidian);
  box-shadow: var(--shadow-subtle-2);
  transition: box-shadow 0.2s ease;
  outline: none;
}

.modern-select {
  width: 100%;
}

.modern-input:focus, .modern-select:focus {
  box-shadow: var(--shadow-subtle-2), 0 0 0 2px var(--color-lime-voltage);
}

.full-width-btn {
  width: 100%;
  margin-top: 24px;
  display: block;
}

.modern-button {
  padding: 16px 28px;
  font-size: 18px;
  font-weight: 700;
  background: var(--color-lime-voltage);
  color: var(--color-forest-ink);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: transform 0.2s ease, opacity 0.2s ease;
  box-shadow: var(--shadow-subtle);
}

.modern-button:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.modern-button:active:not(:disabled) {
  transform: translateY(1px);
}

.modern-button:disabled {
  background: var(--color-pebble);
  color: var(--color-fog);
  box-shadow: none;
  cursor: not-allowed;
}

.category-group label, .price-group label {
  display: block;
  font-size: 14px;
  font-weight: 700;
  color: var(--color-charcoal);
  margin-bottom: 12px;
}

.price-group {
  margin-top: 20px;
}

.full-input {
  width: 100%;
  box-sizing: border-box;
}

.km-group {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid var(--color-fog);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.slider-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.slider-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
  color: var(--color-charcoal);
}

.slider-label strong {
  color: var(--color-obsidian);
  font-weight: 700;
}

.modern-slider {
  -webkit-appearance: none;
  width: 100%;
  height: 8px;
  background: var(--color-fog);
  border-radius: var(--radius-full);
  outline: none;
  box-shadow: var(--shadow-subtle-2);
}

.modern-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-lime-voltage);
  cursor: pointer;
  box-shadow: var(--shadow-subtle);
  transition: transform 0.1s ease;
}

.modern-slider::-webkit-slider-thumb:hover {
  transform: scale(1.1);
}

.loading-state {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  padding: 20px;
  color: var(--color-forest-ink);
  font-weight: 700;
}

.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--color-fog);
  border-top-color: var(--color-lime-voltage);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.alert-error {
  background-color: #fce8e8;
  color: var(--color-alarm-red);
  padding: 16px;
  border-radius: var(--radius-lg);
  margin-bottom: 24px;
  font-weight: 700;
  box-shadow: var(--shadow-subtle);
}

.results-container {
  background: var(--color-paper);
  border-radius: var(--radius-3xl);
  padding: 32px;
  box-shadow: var(--shadow-subtle), var(--shadow-lg);
}

.results-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-fog);
}

.results-title {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.reset-button {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 700;
  color: var(--color-paper);
  background: var(--color-alarm-red);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.reset-button:hover {
  opacity: 0.9;
}

.results-header h2 {
  margin: 0;
  font-size: 25px;
  color: var(--color-obsidian);
  font-weight: 700;
}

.badge {
  background: var(--color-linen-mist);
  color: var(--color-forest-ink);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 700;
  box-shadow: var(--shadow-subtle);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 20px;
  margin-bottom: 24px;
}

.stat-wrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 100%;
}

.stat-label {
  font-size: 12px;
  color: var(--color-slate);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-box {
  background-color: var(--color-paper);
  padding: 20px 16px;
  border-radius: var(--radius-2xl);
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  box-shadow: var(--shadow-subtle);
  flex-grow: 1;
  min-height: 70px;
}

.stat-value {
  font-size: 25px;
  color: var(--color-obsidian);
  font-weight: 700;
  line-height: 1.1;
}

.primary-box {
  background: var(--color-linen-mist);
}

.primary-text {
  color: var(--color-forest-ink);
}

.footer-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: var(--color-charcoal);
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.4s ease, transform 0.4s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
  transform: translateY(-5px);
}

.Logo {
  display: block;
  max-height: 170px;
  max-width: 100%;
  margin: 0 auto 12px;
  object-fit: contain;
}

/* Wise uses stark solid colors rather than vibrant multi-color gradients */
.gradient-text {
  margin: 0;
  font-size: clamp(36px, 8vw, 61px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.915px;
  color: var(--color-forest-ink);
}

.sub-heading {
  transition: color 0.3s ease; 
  font-size: 36px;
  font-weight: 700;
  color: var(--color-obsidian);
  line-height: 1.1;
  margin-bottom: 8px;
}
